import requests
qs=['"C-type natriuretic peptide" AND "sympathetic neurotransmission"','"C-type natriuretic peptide" AND "cardiac sympathetic"','CNP AND "norepinephrine release" AND heart','"Natriuretic peptide receptor-B" AND autonomic','"CNP" AND "sympathetic nerve activity" heart']
for q in qs:
 d=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':15,'retmode':'json','sort':'relevance'},timeout=20).json()['esearchresult']
 ids=d['idlist']
 print('\nQUERY',q,'COUNT',d['count'])
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids:
   print(i,x[i].get('pubdate'),x[i].get('title'))
